import sys, math, json, numpy as np, pandas as pd
sys.path.insert(0,'.')
import harness as H
sys.path.insert(0,'studies/operating_point_sizing')
from operating_point import mondrian_q, ALPHAS, GAMMAS, ACI_BURN_IN
GF='studies/gate_family/results'
for tf in ['5minute','minute']:
    T=H.load(tf); is_idx=np.flatnonzero(T.is_mask); order=is_idx[np.argsort(T.setup_i[is_idx],kind='stable')]
    oof=pd.read_parquet(f'{GF}/oof_{tf}.parquet')
    # how many same-session consecutive units: rows whose setup bar < previous winner's exit bar
    res=json.load(open(f'studies/operating_point_sizing/results_{tf}.json'))
    for sub,model in [('context','hgbc'),('h5_full','scorecard')]:
        m=oof[(oof['sub']==sub)&(oof['model']==model)].set_index('setup_i').loc[T.setup_i[is_idx]]
        p=np.full(T.n,np.nan); p[is_idx]=m['p'].to_numpy(float); s=1-p
        # reproduce conformal alpha 0.1 pooled
        alpha=0.1; keep=np.ones(T.n,bool)
        for f in range(H.N_BLOCKS):
            te=is_idx[T.block[is_idx]==f]; cal=is_idx[(T.block[is_idx]!=f)&T.win[is_idx]]
            keep[te]=s[te]<=mondrian_q(s[cal],alpha)
        kk=keep[is_idx]; W=T.win[is_idx]; net=T.net[is_idx]
        rep=res['models'][f'{sub}/{model}']['conformal'][1]
        print(tf,sub,model,'conformal a=.1 repro: kept',round(kk.mean(),4),'cov',round(kk[W].mean(),4),'diff',round(net[kk].mean()-net[~kk].mean(),2),'| reported',rep['ledger']['kept_share'],rep['winner_coverage'],rep['ledger']['diff'])
        # ACI leak: compare as-coded (label used at setup bar) vs exit-bar-delayed
        for gamma in GAMMAS:
            for alpha in ALPHAS:
                out={}
                for mode in ('coded','delayed'):
                    keep=np.ones(T.n,bool); a_t=alpha; past=[]; pend=[]; n_leak_rows=0; n_leak_used=0
                    for i in order:
                        if mode=='delayed':
                            # release pending winners whose exit bar <= current setup bar
                            still=[]
                            for (xb,sc) in pend:
                                if xb<=T.setup_i[i]:
                                    past.append(sc); a_t=min(1,max(0,a_t+gamma*(alpha-err_of[xb,sc])))
                                else: still.append((xb,sc))
                            pend=still
                        if len(past)<ACI_BURN_IN: keep[i]=True
                        else:
                            q=math.inf if a_t<=0 else (-math.inf if a_t>=1 else mondrian_q(past,a_t)); keep[i]=s[i]<=q
                        if T.win[i]:
                            err=0.0 if keep[i] else 1.0
                            if mode=='coded':
                                a_t=min(1,max(0,a_t+gamma*(alpha-err))); past.append(s[i])
                            else:
                                if 'err_of' not in dir(): err_of={}
                                err_of[(T.exit_bar[i],s[i])]=err; pend.append((T.exit_bar[i],s[i]))
                    out[mode]=keep[is_idx].copy()
                if gamma==0.005 and alpha in (0.05,0.1,0.3):
                    c,d=out['coded'],out['delayed']
                    print(f'  ACI g{gamma} a{alpha}: coded kept {c.mean():.4f} cov {c[W].mean():.4f} diff {net[c].mean()-net[~c].mean():.2f} | delayed kept {d.mean():.4f} cov {d[W].mean():.4f} diff {net[d].mean()-net[~d].mean():.2f} | rows differing {(c!=d).sum()}')
    # count of rows where a previous unit in same session had exit_bar > this setup bar
    prev_exit=-1; cnt=0
    ex=T.exit_bar; su=T.setup_i
    cnt=sum(1 for j,i in enumerate(order[1:],1) if T.win[order[j-1]] and ex[order[j-1]]>su[i])
    print(tf,'IS rows whose immediately preceding unit is a still-open WINNER at this setup bar:',cnt,'of',len(order))
EOF

